import assert from 'node:assert/strict';
import {createNativePassBody} from './native-pass-body.mjs';
import {renderRuntimeBody} from './native-runtime-body.mjs';
const frame={props:0,origin_x:48,origin_y:68,parts:[{dx:0,dy:0,tile:0,attr:0,large:false}],tiles:Buffer.alloc(0x600).toString('base64')};
const cycle={width:96,height:96,ticks:[2,16],frames:[frame,frame]};
const data={schema:'issd-pass-body-local/v2',team:2,kit:'home',skin:0,hair:0,palette:Array(16).fill(0),extra_palette:Array(16).fill(0),cycles:{0:cycle,1:cycle,2:cycle,3:cycle,4:cycle,5:cycle,6:cycle,7:cycle}};
const make=(w,h)=>({width:w,height:h,getContext:()=>({createImageData:()=>({data:new Uint8ClampedArray(w*h*4)}),putImageData(){}})});
const locomotion={schema:'issd-runtime-body-local/v1',cycles:{walking:Array.from({length:8},()=>({height:52}))}};
const preview={schema:'issd-editor-preview-local/v1',teams:Array.from({length:36},()=>({palettes:[Array(16).fill(0),Array(16).fill(1)]}))};
const renderer=createNativePassBody(data,make,locomotion,preview),req={team:2,kit:'home',appearance:{skin_tone:0,hair_style:0},position:'MF',screenDirection:2,palette:Array(16).fill('#000000')};
for(const dir of [0,1,2,3,4,5,6,7])assert.equal(renderer.supports({...req,screenDirection:dir}),true);
for(const team of [0,2,30,35])for(const kit of ['home','away'])for(const skin of [0,1])assert.equal(renderer.supports({...req,team,kit,appearance:{skin_tone:skin,hair_style:0}}),true);
for(const other of [{team:36},{kit:'invalid'},{screenDirection:8},{appearance:{skin_tone:2,hair_style:0}},{appearance:{skin_tone:0,hair_style:1}},{position:'GK'},{palette:[]}])assert.equal(renderer.supports({...req,...other}),false);
assert.equal(renderer.supports({...req,team:30,screenDirection:0}),false);
assert.equal(renderer.supports({...req,kit:'away',screenDirection:0}),false);
assert.equal(renderer.referenceHeight(2),52);assert.equal(renderer.referenceHeight(8),null);
assert.equal(renderer.frame(-1,req),null);assert.equal(renderer.frame(18,req),null);assert.equal(renderer.frame(0,{...req,screenDirection:8}),null);
assert.equal(renderer.frame(0,req),renderer.frame(1,req));assert.equal(renderer.frame(2,req),renderer.frame(17,req));assert.notEqual(renderer.frame(1,req),renderer.frame(2,req));assert.notEqual(renderer.frame(0,{...req,team:30}),renderer.frame(0,req));
assert.throws(()=>createNativePassBody({...data,cycles:{2:{...cycle,ticks:[1,1]}}},make,locomotion,preview));
assert.throws(()=>createNativePassBody(data,make,{schema:'issd-runtime-body-local/v1',cycles:{walking:[]}},preview));
const tiles=Buffer.alloc(0x600);tiles[0]=0x80;
const colors=Array(16).fill('#000000');colors[1]='#ff0000';
const details=Array(16).fill('#000000');details[1]='#00ff00';
const single={width:8,height:8,frames:[{props:10,origin_x:4,origin_y:4,parts:[{dx:0,dy:0,tile:0,attr:0,large:false}],tiles:tiles.toString('base64')}]};
assert.deepEqual([...renderRuntimeBody(single,0,colors,{5:details}).rgba.slice(0,4)],[0,255,0,255],'detail pieces use their own palette');
const indexed=Buffer.alloc(0x600);indexed[0]=0xc0;indexed[1]=0x40;indexed[16]=0x40;
const sampleFrame={...frame,props:2,origin_x:4,origin_y:4,tiles:indexed.toString('base64')};
const sampleCycle={...cycle,frames:[sampleFrame,sampleFrame]};
const localPreview={schema:preview.schema,teams:preview.teams.map(x=>({palettes:x.palettes.map(y=>[...y])}))};
localPreview.teams[30].palettes[0][1]=0x001f;localPreview.teams[30].palettes[1][1]=0x7c00;
const saveCanvas=(w,h)=>{const canvas={width:w,height:h};canvas.getContext=()=>({createImageData:()=>({data:new Uint8ClampedArray(w*h*4)}),putImageData(image){canvas.pixels=image.data;}});return canvas;};
const dynamic=createNativePassBody({...data,cycles:{2:sampleCycle}},saveCanvas,locomotion,localPreview);
const home=Array(16).fill('#000000');home[7]='#00ff00';const away=[...home];away[7]='#ffff00';
const dynamicReq={...req,team:30,palette:home};
const pic=dynamic.frame(0,dynamicReq);assert.deepEqual([...pic.pixels.slice(0,8)],[255,0,0,255,0,255,0,255]);
const other=dynamic.frame(0,{...dynamicReq,kit:'away',palette:away,appearance:{skin_tone:1,hair_style:0}});
assert.deepEqual([...other.pixels.slice(0,8)],[0,0,255,255,255,255,0,255]);
console.log('OK: passe por equipe, uniforme, tom de pele e contextos suportados');
